// Request-session identity (#one-request-one-debug-session). A debug session is bound 1:1 to the
// REQUEST it was spawned for, so the request id IS its identity: one number names the request, its PTY
// pane, and its node on the Glance graph.
//
// It used to name a POOL SLOT (#3535): sessions launched generic and claimed a request only after
// starting, so a slot — a small stable integer with no meaning — was the only identity available before
// the claim landed. Assignment removes that gap. The slot existed to paper over a race that no longer
// happens, and a stable-but-meaningless integer is exactly what made a running session hard to connect
// back to the work it was doing.
//
// The spawn DECISION lives in `poolPlan.ts` (pure, tested); this module is only identity, imported by the
// mount (`RequestSessionsMount`), the Glance graph (`studioProject`), and the team augment (`team.ts`) —
// none of which may reach into the others — so it sits here in shared.

/** The PTY pane id for the session working request `id`. Under the `debug-studio:` prefix so it is
 *  full-capability like the standing debug session (`isFullCapabilitySession`, #3520) — the prefix, not
 *  the singleton id, is what that predicate keys on. */
export function requestPaneId(id: number): string {
  return `debug-studio:req-${id}`;
}

/** The Glance node id for request `id` — distinct from the pane id because the Studio Network's node ids
 *  are team-position ids; {@link requestIdFromNodeId} is the inverse the graph uses to open the session. */
export function requestNodeId(id: number): string {
  return `debugger-req-${id}`;
}

/** The request behind a graph node, or null when the node is not a request session. */
export function requestIdFromNodeId(nodeId: string): number | null {
  const m = /^debugger-req-(\d+)$/.exec(nodeId);
  return m ? Number(m[1]) : null;
}

/** The request behind a PANE id, or null when the pane is not a request session. The mount tracks
 *  sessions by pane id and needs the request back to reconcile them against the queue. */
export function requestIdFromPaneId(paneId: string): number | null {
  const m = /^debug-studio:req-(\d+)$/.exec(paneId);
  return m ? Number(m[1]) : null;
}

